provenance.sourcePrompt:
Biographics quote-card — two sequential cards, 10 seconds total, 1920x1080, SILENT.

Implement the exact Biographics quote-card DOM structure and visual style as described below.

---

## HTML STRUCTURE

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400;1,700&display=swap" rel="stylesheet">
<style>
* { margin:0; padding:0; box-sizing:border-box; }

body {
  width:1920px; height:1080px; overflow:hidden; background:#0a0a0c;
}

#scene {
  width:1920px; height:1080px; position:relative; overflow:hidden;
}

/* ── Background videos ── */
.bg-video {
  position:absolute; top:0; left:0; width:100%; height:100%;
  object-fit:cover; z-index:1; opacity:0.28;
}

/* ── Dark solid overlay ── */
.card-overlay {
  position:absolute; top:0; left:0; width:100%; height:100%;
  z-index:2; background:rgba(8,6,16,0.86);
}

/* ── Quote card wrapper ── */
.quote-card {
  position:absolute; top:0; left:0; width:100%; height:100%;
  z-index:10;
  display:flex; align-items:center; justify-content:center;
}

/* ── Halftone corner decorations ── */
.quote-halftone {
  position:absolute;
  width:220px; height:220px;
  background-image: radial-gradient(circle, rgba(139,46,46,0.22) 1.5px, transparent 1.5px);
  background-size: 12px 12px;
  z-index:11;
  pointer-events:none;
}
.quote-halftone-left  { top:0; left:0; }
.quote-halftone-right { bottom:0; right:0; transform:rotate(180deg); }

/* ── Quote body ── */
.quote-body {
  position:relative; z-index:12;
  display:flex; flex-direction:column; align-items:center;
  width:1100px; text-align:center;
  gap:0;
}

/* ── Rules ── */
.quote-rule {
  width:100%; height:1px;
  background: linear-gradient(to right, transparent, rgba(139,46,46,0.9) 20%, rgba(139,46,46,0.9) 80%, transparent);
}
.quote-rule-top    { margin-bottom:40px; }
.quote-rule-bottom { margin-top:36px; margin-bottom:20px; }

/* ── Quote text ── */
.quote-text {
  font-family:'Playfair Display',Georgia,serif;
  font-size:66px; font-weight:700; font-style:italic;
  color:#f0ece4; line-height:1.28; letter-spacing:0.01em;
  quotes:none;
}
.quote-text::before, .quote-text::after { content:''; }

/* ── Cite ── */
.quote-cite {
  font-family:'Playfair Display',Georgia,serif;
  font-size:16px; font-style:normal; font-weight:400;
  color:rgba(180,160,140,0.78); letter-spacing:0.28em;
  text-transform:uppercase;
}

/* ── Card visibility ── */
#card-1 { opacity:0; }
#card-2 { opacity:0; }
</style>
</head>
<body>
<div id="scene">

  <!-- BG video 1 -->
  <video id="vid1" class="bg-video" autoplay muted loop playsinline>
    <source src="{{bgVid1}}" type="video/mp4">
  </video>
  <!-- BG video 2 (hidden initially) -->
  <video id="vid2" class="bg-video" muted loop playsinline style="opacity:0;">
    <source src="{{bgVid2}}" type="video/mp4">
  </video>

  <!-- CARD 1 -->
  <div class="card-overlay" id="overlay1" style="opacity:0;"></div>
  <div id="card-1" class="quote-card">
    <div class="quote-halftone quote-halftone-left"></div>
    <div class="quote-halftone quote-halftone-right"></div>
    <div class="quote-body">
      <div class="quote-rule quote-rule-top"></div>
      <blockquote class="quote-text">
        "Dormammu,<br>I've come to bargain."
      </blockquote>
      <div class="quote-rule quote-rule-bottom"></div>
      <cite class="quote-cite">Doctor Strange — Marvel Studios, 2016</cite>
    </div>
  </div>

  <!-- CARD 2 -->
  <div class="card-overlay" id="overlay2" style="opacity:0;"></div>
  <div id="card-2" class="quote-card">
    <div class="quote-halftone quote-halftone-left"></div>
    <div class="quote-halftone quote-halftone-right"></div>
    <div class="quote-body">
      <div class="quote-rule quote-rule-top"></div>
      <blockquote class="quote-text">
        "Elementary,<br>my dear Watson."
      </blockquote>
      <div class="quote-rule quote-rule-bottom"></div>
      <cite class="quote-cite">Sherlock — BBC, 2010</cite>
    </div>
  </div>

</div>

<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded', function () {

  var vid2 = document.getElementById('vid2');

  // Initial states
  gsap.set('#overlay1', { opacity: 0 });
  gsap.set('#card-1',   { opacity: 0, y: 18 });
  gsap.set('#overlay2', { opacity: 0 });
  gsap.set('#card-2',   { opacity: 0, y: 18 });
  gsap.set('#vid2',     { opacity: 0 });

  var tl = gsap.timeline();

  // Card 1 in
  tl.to('#overlay1', { opacity: 1, duration: 0.55, ease: 'power2.out' }, 0.0)
    .to('#card-1',   { opacity: 1, y: 0, duration: 0.75, ease: 'power3.out' }, 0.35)

  // Card 1 out → Card 2 in (crossfade ~t=4.2s)
    .to('#card-1',   { opacity: 0, y: -14, duration: 0.55, ease: 'power2.in' }, 4.2)
    .to('#overlay1', { opacity: 0, duration: 0.55, ease: 'power2.in' }, 4.2)
    .call(function() { vid2.play(); }, [], 4.2)
    .to('#vid2',     { opacity: 0.28, duration: 0.55, ease: 'power2.out' }, 4.2)
    .to('#overlay2', { opacity: 1, duration: 0.55, ease: 'power2.out' }, 4.2)
    .to('#card-2',   { opacity: 1, y: 0, duration: 0.75, ease: 'power3.out' }, 4.75)

  // Card 2 out
    .to('#card-2',   { opacity: 0, y: -14, duration: 0.6, ease: 'power2.in' }, 9.1)
    .to('#overlay2', { opacity: 0, duration: 0.6, ease: 'power2.in' }, 9.1);

});
</script>
</body>
</html>
```
